function main({from="-1mon@mon", to="@mon"}) {
    //     
    let rangeFrom = new Time(from)
    let rangeTo = new Time(to)
    let duration = (rangeTo.Unix() - rangeFrom.Unix()) / 86400
    let query = Platform_Metric_QueryBuild(queryOptions("platform_egress_bytes", duration))
    let sinkTableData = Platform_Metric_Query(query, to)

    query = Platform_Metric_QueryBuild(queryOptions("platform_egress_count", duration))
    let sinkTableCount = Platform_Metric_Query(query, to)

    let overallTable = sinkTableData.Clone("_timestamp", "_value")
    overallTable.RenameColumn("_value", "total")
    overallTable.Join(sinkTableCount, ({_timestamp}, {_value: count}) => "inner")
    overallTable.NewColumnLambda("daily", "", (row) => row.total / duration)

    // get summary tickets
    let tickets = getSummaryTickets(rangeFrom, rangeTo)
    overallTable.NewColumnLambda("tickets", "", (row) => tickets)

    return {overallTable}
}

function queryOptions(metric, duration) {
    return {
        metric: metric,
        select: "",
        duration: sprintf("%vd", duration),
        stat: "increase",
        aggregate:"sum",
        groupBy: []
    }
}

function getSummaryTickets(from, to) {
    let hits = 0
    let res = Platform_REST_Call("FluencyAPI", {
        path: "/api/ds/behavior_summary_search",
        debug: false,
        body: {
          kargs: {
            "options": {
        			"facets": {},
        			"fetchLimit": 1,
        			"fetchOffset": 0,
        			"range_field": "from",
        			"range_from": from.UnixMilli(),
        			"range_to": to.UnixMilli(),
        			"searchStr": "riskScore:[3000 TO *]"
        		}
          }
        }
  })

  if (res.data?.verdict == "OK") {
      if (res.data.response?.hits?.total) {
          hits = res.data.response?.hits?.total
      }
  }

  return hits
}
